// Embedded turtle source — martech-ontology.ttl + *-instances.ttl, for the in-browser SPARQL engine (no fetch, works via file://).
const ONTOLOGY_TTL = "# ==========================================================================\n# Unified martech knowledge graph — ontology (v1, schema only, no instance data)\n# Namespace: martech  (placeholder base URI — swap for your real one)\n# Style: RDFS-level only (no OWL reasoning/constraints, intentionally)\n# ==========================================================================\n\n@prefix martech: <https://example.org/martech/ontology/> .\n@prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n\n# --------------------------------------------------------------------------\n# Core classes\n# --------------------------------------------------------------------------\n\nmartech:Requirement a rdfs:Class ;\n    rdfs:comment \"The business problem, question, or hypothesis that justifies tracking something.\" .\n\nmartech:KPI a rdfs:Class ;\n    rdfs:comment \"A measurable objective that addresses a requirement.\" .\n\nmartech:Journey a rdfs:Class ;\n    rdfs:comment \"A named, end-to-end customer path.\" .\n\nmartech:Stage a rdfs:Class ;\n    rdfs:comment \"An ordered step within a journey.\" .\n\nmartech:Component a rdfs:Class ;\n    rdfs:comment \"A metric or dimension from the semantic layer (CJA Semantic Layer MCP). Identity is authoritative in AEP; business meaning (definition, caveats, context) is curated here.\" .\n\nmartech:DataLayerVariable a rdfs:Class ;\n    rdfs:comment \"The raw implementation artifact (e.g. a data layer field) that populates a component.\" .\n\n# --------------------------------------------------------------------------\n# N-ary relation classes\n#\n# Used where a relationship itself needs an attribute (e.g. a filter value).\n# A plain RDF predicate can only connect two resources with no attribute of\n# its own, so this relationship is modeled as its own node instead of a\n# plain triple.\n# Pattern reference: https://www.w3.org/TR/swbp-n-aryRelations/\n# --------------------------------------------------------------------------\n\nmartech:Measurement a rdfs:Class ;\n    rdfs:comment \"A 'measured_by' relationship between a Stage and a Component, optionally qualified by a filter value (e.g. a specific page-name value that identifies the stage).\" .\n\n# --------------------------------------------------------------------------\n# Direct predicates (no attributes of their own)\n# --------------------------------------------------------------------------\n\nmartech:addressed_by a rdf:Property ;\n    rdfs:domain martech:Requirement ;\n    rdfs:range martech:KPI ;\n    rdfs:comment \"Links a requirement to the KPI that measures it.\" .\n\nmartech:has_stage a rdf:Property ;\n    rdfs:domain martech:Journey ;\n    rdfs:range martech:Stage ;\n    rdfs:comment \"Links a journey to one of its ordered stages.\" .\n\nmartech:rolls_up_to a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range martech:KPI ;\n    rdfs:comment \"Links a stage's outcome to the KPI it contributes to.\" .\n\nmartech:maps_to a rdf:Property ;\n    rdfs:domain martech:DataLayerVariable ;\n    rdfs:range martech:Component ;\n    rdfs:comment \"Links a raw implementation variable to the semantic component it populates.\" .\n\nmartech:refs a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range rdfs:Resource ;\n    rdfs:comment \"Points to the authoritative entity in AEP's own native knowledge graph (e.g. an XDM path URI). Reference only — never duplicated locally.\" .\n\n# --------------------------------------------------------------------------\n# N-ary relation predicates\n# --------------------------------------------------------------------------\n\nmartech:measured_entity a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range rdfs:Resource ;\n    rdfs:comment \"The Stage being measured.\" .\n\nmartech:measured_component a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range martech:Component ;\n    rdfs:comment \"The component used to measure the entity.\" .\n\nmartech:filter_value a rdf:Property ;\n    rdfs:domain martech:Measurement ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Optional. The specific dimension value that identifies this measurement (e.g. a page-name value for a shared page-name component).\" .\n\n# --------------------------------------------------------------------------\n# Datatype properties (business-meaning / descriptive attributes)\n# --------------------------------------------------------------------------\n\nmartech:status a rdf:Property ;\n    rdfs:domain martech:Requirement ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Lifecycle status of a requirement, e.g. active, answered, retired.\" .\n\nmartech:formula a rdf:Property ;\n    rdfs:domain martech:KPI ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"The formula or definition of a KPI.\" .\n\nmartech:target a rdf:Property ;\n    rdfs:domain martech:KPI ;\n    rdfs:range xsd:decimal ;\n    rdfs:comment \"The target or benchmark value for a KPI.\" .\n\nmartech:order a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range xsd:integer ;\n    rdfs:comment \"Position of the stage within its journey.\" .\n\nmartech:entry_criteria a rdf:Property ;\n    rdfs:domain martech:Stage ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"What defines that a user has entered this stage.\" .\n\nmartech:definition a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Plain-language business meaning of the component. Curated here — not present in AEP's own graph.\" .\n\nmartech:caveats a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Known data-quality issues, gaps, or limitations of the component.\" .\n\nmartech:context a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Business or industry context explaining why the component matters.\" .\n\nmartech:component_type a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Whether the component is a metric or a dimension.\" .\n\nmartech:is_pii a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:boolean ;\n    rdfs:comment \"Whether the component carries or is derived from personally identifiable information.\" .\n\nmartech:governance_notes a rdf:Property ;\n    rdfs:domain martech:Component ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Data governance notes: consent requirements, data quality/retention concerns, or other compliance-relevant context.\" .\n\nmartech:source_system a rdf:Property ;\n    rdfs:domain martech:DataLayerVariable ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Where the raw variable is implemented, e.g. the tagging/data layer system.\" .\n\nmartech:owner a rdf:Property ;\n    rdfs:range xsd:string ;\n    rdfs:comment \"Person or team responsible. Reused across Requirement, KPI, Journey, and Component — intentionally left without a fixed domain.\" .\n";
const ECOMMERCE_TTL = "@prefix data: <https://example.org/martech/data/ecommerce/> .\r\n@prefix martech: <https://example.org/martech/ontology/> .\r\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\r\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\r\n\r\ndata:dlv_conversion_funnel_step a martech:DataLayerVariable ;\r\n    rdfs:label \"digitalData.conversion.conversionFunnel.step\" ;\r\n    martech:maps_to data:component_checkouts,\r\n        data:component_orders,\r\n        data:component_product_list_adds,\r\n        data:component_product_views ;\r\n    martech:source_system \"Web data layer (digitalData)\" .\r\n\r\ndata:journey_ecommerce_funnel a martech:Journey ;\r\n    rdfs:label \"Ecommerce purchase journey\" ;\r\n    martech:has_stage data:stage_cart_add,\r\n        data:stage_checkout,\r\n        data:stage_order,\r\n        data:stage_product_view ;\r\n    martech:owner \"Digital Marketing\" .\r\n\r\ndata:measurement_cart_add a martech:Measurement ;\r\n    martech:measured_component data:component_product_list_adds ;\r\n    martech:measured_entity data:stage_cart_add .\r\n\r\ndata:measurement_checkout a martech:Measurement ;\r\n    martech:measured_component data:component_checkouts ;\r\n    martech:measured_entity data:stage_checkout .\r\n\r\ndata:measurement_order a martech:Measurement ;\r\n    martech:measured_component data:component_orders ;\r\n    martech:measured_entity data:stage_order .\r\n\r\ndata:measurement_product_view a martech:Measurement ;\r\n    martech:measured_component data:component_product_views ;\r\n    martech:measured_entity data:stage_product_view .\r\n\r\ndata:req_shop_performance a martech:Requirement ;\r\n    rdfs:label \"Understand shop performance and drop-off\" ;\r\n    rdfs:comment \"We want to understand how our shop is performing, and where in the journey people drop off.\" ;\r\n    martech:addressed_by data:kpi_order_conversion_rate ;\r\n    martech:status \"active\" .\r\n\r\ndata:component_checkouts a martech:Component ;\r\n    rdfs:label \"Checkouts\" ;\r\n    martech:caveats \"Counts checkout starts, not completions — a user can start checkout multiple times without purchasing.\" ;\r\n    martech:component_type \"metric\" ;\r\n    martech:context \"Marks the transition from browsing to transactional intent.\" ;\r\n    martech:definition \"Number of times a user started the checkout process.\" ;\r\n    martech:owner \"Digital Analytics\" ;\r\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.checkouts.value> .\r\n\r\ndata:component_orders a martech:Component ;\r\n    rdfs:label \"Orders\" ;\r\n    martech:caveats \"Includes orders later cancelled or refunded — not net of returns.\" ;\r\n    martech:component_type \"metric\" ;\r\n    martech:context \"The funnel's terminal event and the numerator of the order conversion rate KPI.\" ;\r\n    martech:definition \"Number of completed purchase orders.\" ;\r\n    martech:owner \"Digital Analytics\" ;\r\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/orders> .\r\n\r\ndata:component_product_list_adds a martech:Component ;\r\n    rdfs:label \"Product list adds\" ;\r\n    martech:caveats \"Does not deduplicate repeated adds of the same product within one session.\" ;\r\n    martech:component_type \"metric\" ;\r\n    martech:context \"First explicit purchase-intent signal in the funnel.\" ;\r\n    martech:definition \"Number of times a product was added to the cart.\" ;\r\n    martech:owner \"Digital Analytics\" ;\r\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.productListAdds.value> .\r\n\r\ndata:component_product_views a martech:Component ;\r\n    rdfs:label \"Product views\" ;\r\n    martech:caveats \"Counts page views, not unique visitors — a visitor viewing the same product twice counts twice.\" ;\r\n    martech:component_type \"metric\" ;\r\n    martech:context \"Entry point for the purchase funnel; used to benchmark top-of-funnel demand.\" ;\r\n    martech:definition \"Number of times a product detail page was viewed.\" ;\r\n    martech:owner \"Digital Analytics\" ;\r\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/commerce.productViews.value> .\r\n\r\ndata:kpi_order_conversion_rate a martech:KPI ;\r\n    rdfs:label \"Order conversion rate\" ;\r\n    rdfs:comment \"Current value (2026): 0.11%. Target: 0.20% (illustrative example, not a real commitment).\" ;\r\n    martech:formula \"Orders / Product Views\" ;\r\n    martech:owner \"Ecommerce / Digital Marketing\" ;\r\n    martech:target 0.0020 .\r\n\r\ndata:stage_cart_add a martech:Stage ;\r\n    rdfs:label \"Cart add\" ;\r\n    martech:order 2 .\r\n\r\ndata:stage_checkout a martech:Stage ;\r\n    rdfs:label \"Checkout\" ;\r\n    martech:order 3 .\r\n\r\ndata:stage_order a martech:Stage ;\r\n    rdfs:label \"Order\" ;\r\n    martech:order 4 ;\r\n    martech:rolls_up_to data:kpi_order_conversion_rate .\r\n\r\ndata:stage_product_view a martech:Stage ;\r\n    rdfs:label \"Product view\" ;\r\n    martech:order 1 .\r\n\r\n";
const LOGIN_TTL = "@prefix data: <https://example.org/martech/data/login/> .\r\n@prefix martech: <https://example.org/martech/ontology/> .\r\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\r\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\r\n\r\ndata:dlv_page_info_name a martech:DataLayerVariable ;\r\n    rdfs:label \"digitalData.page.pageInfo.name\" ;\r\n    martech:maps_to data:component_page_name ;\r\n    martech:source_system \"Web data layer (digitalData)\" .\r\n\r\ndata:journey_login a martech:Journey ;\r\n    rdfs:label \"Customer login journey\" ;\r\n    martech:has_stage data:stage_login,\r\n        data:stage_login_success ;\r\n    martech:owner \"Product Analytics\" .\r\n\r\ndata:measurement_login a martech:Measurement ;\r\n    martech:filter_value \"/customer/login\" ;\r\n    martech:measured_component data:component_page_name ;\r\n    martech:measured_entity data:stage_login .\r\n\r\ndata:measurement_login_success a martech:Measurement ;\r\n    martech:filter_value \"/customer/login/success\" ;\r\n    martech:measured_component data:component_page_name ;\r\n    martech:measured_entity data:stage_login_success .\r\n\r\ndata:req_login_frequency a martech:Requirement ;\r\n    rdfs:label \"Understand monthly login frequency\" ;\r\n    rdfs:comment \"We want to know how many logins we have monthly (MAU), and how that compares to overall sessions.\" ;\r\n    martech:addressed_by data:kpi_login_rate ;\r\n    martech:status \"active\" .\r\n\r\ndata:kpi_login_rate a martech:KPI ;\r\n    rdfs:label \"Monthly login rate\" ;\r\n    rdfs:comment \"Target: 35% of monthly sessions include a login (illustrative example, not a real commitment).\" ;\r\n    martech:formula \"Monthly logins / Sessions\" ;\r\n    martech:owner \"Product Analytics\" ;\r\n    martech:target 0.35 .\r\n\r\ndata:stage_login a martech:Stage ;\r\n    rdfs:label \"Login\" ;\r\n    martech:order 1 .\r\n\r\ndata:stage_login_success a martech:Stage ;\r\n    rdfs:label \"Login success\" ;\r\n    martech:order 2 ;\r\n    martech:rolls_up_to data:kpi_login_rate .\r\n\r\ndata:component_page_name a martech:Component ;\r\n    rdfs:label \"Page name\" ;\r\n    martech:caveats \"A shared, general-purpose dimension — filtering by value (e.g. /customer/login) is required to isolate a specific journey step. The raw component alone doesn't identify a stage.\" ;\r\n    martech:component_type \"dimension\" ;\r\n    martech:context \"A general-purpose dimension, likely reused by other journeys in a real implementation — filtering by value is what distinguishes each specific use, not the component itself.\" ;\r\n    martech:definition \"The page name/path captured on each page view; used here to identify funnel steps by value.\" ;\r\n    martech:owner \"Digital Analytics\" ;\r\n    martech:refs <https://sandbox/SANDBOX_NAME/xdm/web.webPageDetails.name> .\r\n\r\n";
